sys_variable_value.value:
(function execute(inputs, outputs) {
    var dtArray = [];
    var i = 0;
    var dt_req = new GlideRecord('x_snc_duty_travel_duty_travel_req');
    dt_req.addEncodedQuery('traveller='+inputs.traveller.sys_id);
    dt_req.orderByDesc('sys_created_on');
    dt_req.setLimit(15);
    dt_req.query();

    while(dt_req.next()) {
        var dtObject = {};
        dtObject.number = dt_req.getValue('number');
        dtObject.traveller = dt_req.getDisplayValue('traveller');
        dtObject.airline = dt_req.getDisplayValue('airline');
        dtObject.leaving_from = dt_req.getDisplayValue('leaving_from');
        dtObject.going_to = dt_req.getDisplayValue('going_to');
        dtObject.trip_type = dt_req.getDisplayValue('trip_type');
        dtObject.cabin_class = dt_req.getDisplayValue('cabin_class');
        dtObject.departing_on = dt_req.getDisplayValue('departing_on');
        dtObject.returning_on = dt_req.getDisplayValue('returning_on');
        dtObject.business_justification = dt_req.getDisplayValue('business_justification');
        dtObject.submit_date = dt_req.getDisplayValue('sys_created_on');
        dtArray[i] = dtObject;
        i += 1;
    }
    outputs.dt_reqs = dtArray;

})(inputs, outputs);

